CREATE TABLE IF NOT EXISTS admin_users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('super_admin','admin')),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_otp_codes(id TEXT PRIMARY KEY,email TEXT NOT NULL,code_hash TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_admin_otp_email_created ON admin_otp_codes(email,created_at);
CREATE TABLE IF NOT EXISTS admin_sessions(id TEXT PRIMARY KEY,admin_id TEXT NOT NULL REFERENCES admin_users(id),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_expiry ON admin_sessions(expires_at);
CREATE TABLE IF NOT EXISTS admin_audit_log(id TEXT PRIMARY KEY,admin_email TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_api_errors(id TEXT PRIMARY KEY,route TEXT NOT NULL,method TEXT NOT NULL,error_code TEXT,message TEXT,admin_email TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customer_applications(id TEXT PRIMARY KEY,reseller_id TEXT,customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,customer_email TEXT,nin TEXT,occupation TEXT,monthly_income_ugx INTEGER,guarantor_json TEXT,device_json TEXT,finance_plan_json TEXT,kyc_media_json TEXT,deposit_amount_ugx INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',decision_reason TEXT,reviewed_by TEXT,reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customer_applications_status_created ON customer_applications(status,created_at);
CREATE TABLE IF NOT EXISTS reseller_commission_settings(reseller_id TEXT PRIMARY KEY,rate_percent REAL NOT NULL DEFAULT 0,fixed_amount_ugx INTEGER NOT NULL DEFAULT 0,applies_to TEXT NOT NULL DEFAULT 'received_payment',active INTEGER NOT NULL DEFAULT 1,updated_by TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reseller_commissions(id TEXT PRIMARY KEY,reseller_id TEXT NOT NULL,customer_application_id TEXT,payment_reference TEXT NOT NULL UNIQUE,payment_amount_ugx INTEGER NOT NULL,rate_percent REAL NOT NULL,fixed_amount_ugx INTEGER NOT NULL,commission_amount_ugx INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_reseller_commissions_status_created ON reseller_commissions(status,created_at);
CREATE TABLE IF NOT EXISTS reseller_withdrawals(id TEXT PRIMARY KEY,reseller_id TEXT NOT NULL,amount_ugx INTEGER NOT NULL,payout_method TEXT,payout_reference TEXT,status TEXT NOT NULL DEFAULT 'pending',requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_by TEXT,reviewed_at TEXT,decision_reason TEXT);
CREATE INDEX IF NOT EXISTS idx_reseller_withdrawals_status_requested ON reseller_withdrawals(status,requested_at);
